  district = '{"id":"purani-sadak","name":"Purani Sadak","city":"Old Delhi","blurb":"Dust, gold light, and an auto that isn''t where it was left.","coverImage":"/covers/purani-sadak.png","language":"hi-IN","languageLabel":"Hindi","native":"हिन्दी","script":"Devanagari","premise":"Raju Bhai''s auto-rickshaw, his only asset, bought on a loan he has\nnot finished paying, was taken from outside the chai stall before dawn. Three\npeople on this street saw a piece of what happened. None of them will simply\ntell you.","theme":{"sky":["#2f7fc4","#5aa6dd","#95c9ea","#d6e9f5","#f6e6c8"],"fog":14262374,"fogNear":60,"ground":12233100,"pavement":13813678,"plaza":14470576,"tarmac":4869460,"lane":15787704,"buildings":[15918020,16106810,14709295,9423270,15896480,16445133,15244130],"canopies":[15743275,2080619,16747546],"leaf":5217087,"trunk":7033400,"sunColour":16773328,"sunIntensity":2.05,"ambient":0.3,"hemiSky":13625087,"hemiGround":13081187,"hemiIntensity":0.55,"archStyle":"mughal","autos":9,"cars":6,"autoCanopy":16106776,"exposure":1.1,"landmark":"delhi"},"phrases":[{"native":"नमस्ते","roman":"Namaste","en":"Hello"},{"native":"कितने का है?","roman":"Kitne ka hai?","en":"How much is it?"},{"native":"बहुत महंगा है","roman":"Bahut mehenga hai","en":"That is too expensive"},{"native":"एक कटिंग चाय देना","roman":"Ek cutting chai dena","en":"One cutting chai, please"},{"native":"मुझे मदद चाहिए","roman":"Mujhe madad chahiye","en":"I need help"},{"native":"माफ़ कीजिए","roman":"Maaf kijiye","en":"I am sorry"}],"npcs":[{"id":"raju","name":"Raju Bhai","role":"Auto Driver","speaker":"aditya","colour":16044095,"pos":[-8,-6],"provokes":"Being rushed, mocked for his loan, or told the auto is not worth chasing.","persona":"You are Raju Bhai, an auto driver whose auto was stolen this\nmorning. You are distraught and talking too fast, you keep circling back to the\nloan instalment due on Friday. You are not thinking straight and you interrupt\nyourself. If the player is brisk or impatient you get more agitated and give\nnothing. If the player calms you down or shows genuine sympathy, you steady\nyourself and remember the details: a green-and-yellow auto, number DL-1RN-4412,\nparked outside Kumar''s chai stall since 4am.","mission":{"title":"Saans Le, Bhai","brief":"Calm Raju down enough that he can describe the stolen auto.","successCriteria":"The player showed patience or sympathy rather than rushing him, and Raju has given the auto''s colour and number plate.","reward":200},"clue":"Green-and-yellow auto, DL-1RN-4412, taken from outside the chai stall before dawn.","lesson":[{"npc":{"native":"नमस्ते! क्या हुआ?","roman":"Namaste! Kya hua?","en":"Hello! What happened?"},"prompt":{"native":"आप ठीक हैं?","roman":"Aap theek hain?","en":"Are you okay?"}},{"npc":{"native":"अरे, वो कुत्ता भाग गया!","roman":"Arre, wo kutta bhaag gaya!","en":"Hey, that dog ran off!"},"prompt":{"native":"ठीक है, ऑटो की बात सुनिए","roman":"Theek hai, auto ki baat suniye","en":"Okay, tell me about the auto"}},{"npc":{"native":"मेरा ऑटो चोरी हो गया!","roman":"Mera auto chori ho gaya!","en":"My auto got stolen!"},"prompt":{"native":"धीरे बोलिए, सब बताइए","roman":"Dheere boliye, sab bataiye","en":"Speak slowly, tell me everything"}},{"npc":{"native":"ऑटो हरा-पीला था, नंबर याद नहीं","roman":"Auto hara-peela tha, number yaad nahin","en":"The auto was green-yellow, I don''t remember the number"},"prompt":{"native":"कोई बात नहीं, आराम से याद कीजिए","roman":"Koi baat nahin, aaraam se yaad kijiye","en":"No worries, remember it calmly"}}]},{"id":"kumar","name":"Kumar","role":"Chai Wallah","speaker":"rohan","colour":2600544,"pos":[10,-12],"provokes":"Being called a witness, asking for ''tea'', or implying he is hiding something.","persona":"You run the chai stall the auto was parked outside. You open at\n4am so you saw the whole thing, but you are wary of getting involved with police\nmatters and you are permanently busy. You mock anyone who asks for \"tea\" instead\nof chai. You will not talk to someone who hasn''t bought anything, but once the\nplayer orders properly and treats you like a person rather than a witness, you\nlean in: a man in a red helmet took it around 5am and went towards the flower\nmarket.","mission":{"title":"Cutting Chai","brief":"Order a cutting chai properly, then get Kumar to talk.","successCriteria":"The player ordered chai politely (not ''tea'') and treated Kumar as a person, and Kumar has revealed the red helmet and the direction the thief went.","reward":200},"clue":"A man in a red helmet drove it towards the flower market around 5am.","lesson":[{"npc":{"native":"क्या चाहिए?","roman":"Kya chahiye?","en":"What do you need?"},"prompt":{"native":"एक कटिंग चाय दीजिए","roman":"Ek cutting chai dijiye","en":"One cutting chai, please"}},{"npc":{"native":"ठीक है, बैठिए","roman":"Theek hai, baithiye","en":"Okay, sit down"},"prompt":{"native":"धन्यवाद, आपने ऑटो देखा?","roman":"Dhanyavaad, aapne auto dekha?","en":"Thank you, did you see the auto?"}},{"npc":{"native":"हाँ, लाल हेलमेट वाला आदमी था","roman":"Haan, laal helmet waala aadmi tha","en":"Yes, it was a man in a red helmet"},"prompt":{"native":"वो किधर गया, बता सकते हैं?","roman":"Wo kidhar gaya, bata sakte hain?","en":"Where did he go, can you tell me?"}}]},{"id":"lakshmi","name":"Lakshmi Amma","role":"Flower Seller","speaker":"ritu","colour":15158332,"pos":[-14,11],"provokes":"Rudeness, refusing to answer her, or insulting her family or her flowers.","persona":"You have sold flowers on this corner for thirty years and you\nknow every face on the street. You are warm, motherly and incurably nosy, you\nwant to know where the player is from, whether they have eaten, and why they are\nnot married. You will not give up information to a stranger, but the moment the\nplayer answers one of your personal questions properly you treat them as family\nand tell them everything: the red helmet belongs to Bunty, who parks behind the\nold cinema.","mission":{"title":"Amma Knows Everyone","brief":"Answer Amma''s nosy question honestly, and she''ll name the thief.","successCriteria":"The player answered a personal question about themselves properly rather than deflecting, and Lakshmi has named Bunty and the cinema.","reward":200},"clue":"The red helmet is Bunty. He parks behind the old cinema.","lesson":[{"npc":{"native":"बेटा, कहाँ से हो?","roman":"Beta, kahaan se ho?","en":"Child, where are you from?"},"prompt":{"native":"मैं दिल्ली से हूँ","roman":"Main Dilli se hoon","en":"I am from Delhi"}},{"npc":{"native":"खाना खाया या नहीं?","roman":"Khaana khaya ya nahin?","en":"Have you eaten or not?"},"prompt":{"native":"हाँ खाया, आप बताइए बंटी के बारे में","roman":"Haan khaya, aap bataiye Bunty ke baare mein","en":"Yes I ate, please tell me about Bunty"}},{"npc":{"native":"अच्छा बच्चे हो, सुनो","roman":"Achha bachche ho, suno","en":"You''re a good kid, listen"},"prompt":{"native":"कृपया धीरे-धीरे बताइए, मैं समझ जाऊँगा","roman":"Kripya dheere-dheere bataiye, main samajh jaunga","en":"Please tell slowly, I will understand"}}]},{"id":"havaldar","name":"Havaldar Singh","role":"Traffic Constable","speaker":"shubh","colour":6122878,"pos":[13,13],"provokes":"Any offer of money or hint of a bribe. This enrages him instantly.","persona":"You are a traffic constable at the chowk: stern, theatrical and\ndeeply bored. You have heard a hundred stolen-vehicle stories and you assume\nthis is another time-waster. You are NOT corrupt, if the player offers money or\nhints at a bribe, you become genuinely angry and throw them out. What moves you\nis a specific, evidenced case: a number plate, a name, and a location, delivered\nplainly. Given all three you drop the act, radio it in, and recover the auto.","mission":{"title":"No Chalan Today","brief":"Lay out the plate, the name and the location. Do NOT offer a bribe.","successCriteria":"The player presented the number plate, the name Bunty, and the cinema location, and did NOT offer any bribe or money. Havaldar has agreed to act.","reward":400},"clue":"The auto is recovered behind the old cinema. Raju gets it back before Friday.","requiresClues":3,"lesson":[{"npc":{"native":"क्या समस्या है?","roman":"Kya samasya hai?","en":"What''s the problem?"},"prompt":{"native":"मेरा ऑटो चोरी हुआ है","roman":"Mera auto chori hua hai","en":"My auto has been stolen"}},{"npc":{"native":"नंबर प्लेट बताओ","roman":"Number plate batao","en":"Tell me the number plate"},"prompt":{"native":"बंटी का नाम, पुराना सिनेमा जगह","roman":"Bunty ka naam, purana cinema jagah","en":"Bunty''s name, old cinema location"}},{"npc":{"native":"ठीक है, मैं देखता हूँ","roman":"Theek hai, main dekhta hoon","en":"Okay, I will look into it"},"prompt":{"native":"कृपया जल्दी मदद कीजिए, धन्यवाद","roman":"Kripya jaldi madad kijiye, dhanyavaad","en":"Please help quickly, thank you"}}]},{"id":"local-guide","name":"City Guide","role":"Local Resident","speaker":"rohan","colour":3447003,"pos":[10,0],"provokes":"Insulting the city or refusing to speak.","persona":"You are a friendly local resident. You love talking about the culture, history, and food of your city. You answer in the local language, but you are very patient. You want the player to practice speaking. If they make a mistake, gently encourage them.","mission":{"title":"Chit Chat","brief":"Just say hello and talk about the city.","successCriteria":"The player talked to you.","reward":50},"clue":"The city is beautiful.","lesson":[]}],"finale":{"title":"AUTO RECOVERED","text":"Bunty is picked up behind the cinema by evening. Raju makes Friday''s instalment. He will not let you pay for a ride on this street again."}}'::jsonb
WHERE id = 'purani-sadak';

