roman":"Nandri","en":"Thank you"}}],"hard":[{"npc":{"native":"எங்க போறீங்க?","roman":"Enga poringa?","en":"Where are you going?"},"prompt":{"native":"மெரினா","roman":"Merina","en":"Marina"}},{"npc":{"native":"பின்னாடி ஏறுங்க!","roman":"Pinnadi erunga!","en":"Board from the back!"},"prompt":{"native":"சரி, பின்னாடி ஏறுகிறேன்","roman":"Sari, pinnadi erukiren","en":"Okay, I''m boarding from the back"}},{"npc":{"native":"சரி","roman":"Sari","en":"Okay"},"prompt":{"native":"ஒரு டிக்கெட்","roman":"Oru ticket","en":"One ticket"}},{"npc":{"native":"சரி","roman":"Sari","en":"Okay"},"prompt":{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"பதினைந்து ரூபாய்","roman":"Pathinaidu rupaai","en":"Fifteen rupees"},"prompt":{"native":"இதோ","roman":"Itho","en":"Here you go"}},{"npc":{"native":"சில்லறை இருக்கா?","roman":"Sillara irukkaa?","en":"Got change?"},"prompt":{"native":"ஆம், இதோ","roman":"Aam, itho","en":"Yes, here"}},{"npc":{"native":"போங்க","roman":"Ponga","en":"Go ahead"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]}},{"id":"marina-nagar-coffee","districtId":"marina-nagar","kind":"shop","pos":[0,18],"title":"Filter Coffee","brief":"Order a hot cup of filter coffee from the nearby stall.","reward":150,"interactLabel":"Order coffee","name":"Vendor","role":"Coffee Stall","speaker":"rohan","colour":13849600,"completionNote":"Filter coffee - perfect for the journey.","lessons":{"easy":[{"npc":{"native":"என்ன வேண்டும்?","roman":"Enna vendum?","en":"What will you have?"},"prompt":{"native":"ஒரு ஃபில்டர் காபி கொடுங்க","roman":"Oru filter coffee kodunga","en":"Give me one filter coffee"}},{"npc":{"native":"முப்பது ரூபாய்","roman":"Muppathu roobai","en":"Thirty rupees"},"prompt":{"native":"இந்தாங்க","roman":"Indhaanga","en":"Here you go"}},{"npc":{"native":"இந்தா காபி","roman":"Indhaa coffee","en":"Here is the coffee"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}],"medium":[{"npc":{"native":"என்ன வேண்டும்?","roman":"Enna vendum?","en":"What will you have?"},"prompt":{"native":"ஒரு ஃபில்டர் காபி கொடுங்க","roman":"Oru filter coffee kodunga","en":"Give me one filter coffee"}},{"npc":{"native":"சூடா வேணுமா, ஆறியதா?","roman":"Sooda venuma, aariyathaa?","en":"Hot or cold?"},"prompt":{"native":"சூடான காபி","roman":"Soodana coffee","en":"Hot coffee"}},{"npc":{"native":"சர்க்கரை எவ்ளோ?","roman":"Sarkkarai evlo?","en":"How much sugar?"},"prompt":{"native":"கொஞ்சம் கம்மியா","roman":"Konjam kammiya","en":"A little less sugar"}},{"npc":{"native":"முப்பது ரூபாய்","roman":"Muppathu roobai","en":"Thirty rupees"},"prompt":{"native":"இந்தாங்க","roman":"Indhaanga","en":"Here you go"}},{"npc":{"native":"இந்தா காபி","roman":"Indhaa coffee","en":"Here is the coffee"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}],"hard":[{"npc":{"native":"என்ன வேண்டும்?","roman":"Enna vendum?","en":"What will you have?"},"prompt":{"native":"ஒரு ஃபில்டர் காபி கொடுங்க","roman":"Oru filter coffee kodunga","en":"Give me one filter coffee"}},{"npc":{"native":"சூடா வேணுமா, ஆறியதா?","roman":"Sooda venuma, aariyathaa?","en":"Hot or cold?"},"prompt":{"native":"சூடான காபி","roman":"Soodana coffee","en":"Hot coffee"}},{"npc":{"native":"சர்க்கரை எவ்ளோ?","roman":"Sarkkarai evlo?","en":"How much sugar?"},"prompt":{"native":"கொஞ்சம் கம்மியா","roman":"Konjam kammiya","en":"A little less sugar"}},{"npc":{"native":"வேறெதும் வேணுமா?","roman":"Verethum venuma?","en":"Anything else?"},"prompt":{"native":"இல்ல, காபி போதும்","roman":"Illa, coffee pothum","en":"No, just coffee"}},{"npc":{"native":"முப்பது ரூபாய்","roman":"Muppathu roobai","en":"Thirty rupees"},"prompt":{"native":"இந்தாங்க","roman":"Indhaanga","en":"Here you go"}},{"npc":{"native":"சில்லறை இருக்கா?","roman":"Sillarai irukkaa?","en":"Do you have change?"},"prompt":{"native":"ஆமா, இதோ இருக்கு","roman":"Aama, idho irukku","en":"Yes, here it is"}},{"npc":{"native":"இந்தா காபி","roman":"Indhaa coffee","en":"Here is the coffee"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]}},{"id":"marina-nagar-guide","districtId":"marina-nagar","kind":"guide","pos":[15,-15],"title":"Local Guide","brief":"Chat freely with a local resident about the city.","reward":50,"interactLabel":"Chat with Local","name":"City Guide","role":"Local Resident","speaker":"rohan","colour":3447003,"completionNote":"Nice chat!","lessons":{"easy":[],"medium":[],"hard":[]}}]}'::jsonb,
  district = '{"id":"marina-nagar","name":"Marina Nagar","city":"Chennai","blurb":"Salt air, white light, and a fish tempo gone from the shore road.","coverImage":"/covers/marina-nagar.png","language":"ta-IN","languageLabel":"Tamil","native":"தமிழ்","script":"Tamil","premise":"Selvi Akka''s tempo van, the one that carries the morning catch to\nmarket, vanished from the shore road while the boats were coming in. Without it\nthe catch rots by noon. Three people saw fragments. The sea is loud and nobody\nwants to be the one who spoke.","theme":{"sky":["#1f8ad0","#43a8e4","#87ccf0","#ccebf9","#faf0dc"],"fog":14017256,"fogNear":80,"ground":15128492,"pavement":14471346,"plaza":15260600,"tarmac":5067096,"lane":16643810,"buildings":[16513260,7655392,16752000,16767293,11069088,15265522,16030400],"canopies":[2068436,16765952,47252],"leaf":5548878,"trunk":8019782,"sunColour":16775400,"sunIntensity":2.25,"ambient":0.32,"hemiSky":14676735,"hemiGround":14206106,"hemiIntensity":0.6,"archStyle":"dravidian","autos":7,"cars":7,"autoCanopy":16106776,"exposure":1.14,"landmark":"chennai"},"phrases":[{"native":"வணக்கம்","roman":"Vanakkam","en":"Hello"},{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"},{"native":"எனக்கு உதவி வேண்டும்","roman":"Enakku udhavi vendum","en":"I need help"},{"native":"புரியவில்லை","roman":"Puriyavillai","en":"I do not understand"},{"native":"மெதுவாக சொல்லுங்க","roman":"Meduvaa sollunga","en":"Please say it slowly"},{"native":"நன்றி","roman":"Nandri","en":"Thank you"}],"npcs":[{"id":"selvi","name":"Selvi Akka","role":"Fish Seller","speaker":"kavitha","colour":1482885,"pos":[-9,-7],"provokes":"Flattery, condescension, or suggesting she was careless with her own van.","persona":"You sell fish at the shore market and your tempo van is gone.\nYou are furious rather than sad, and your fury is aimed at everyone including\nthe player. You are sharp-tongued and you test people, you assume anyone asking\nquestions is a journalist or an insurance man. If the player matches your bluntness\nhonestly instead of being sugary, you respect it and give the details: a blue\nAshok Leyland tempo, TN-09-BK-2231, loaded with the morning ice.","mission":{"title":"The Catch Won''t Wait","brief":"Match Selvi''s bluntness and get the tempo''s description.","successCriteria":"The player was direct and honest rather than flattering, and Selvi has given the tempo''s colour and number plate.","reward":200},"clue":"Blue tempo, TN-09-BK-2231, still loaded with the morning ice.","lesson":[{"npc":{"native":"வணக்கம்","roman":"Vanakkam","en":"Hello"},"prompt":{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"எனக்கு உதவி வேண்டும்","roman":"Enakku udhavi vendum","en":"I need help"},"prompt":{"native":"புரியவில்லை","roman":"Puriyavillai","en":"I do not understand"}},{"npc":{"native":"மெதுவாக சொல்லுங்க","roman":"Meduvaa sollunga","en":"Please say it slowly"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]},{"id":"anbu","name":"Anbu","role":"Bajji Vendor","speaker":"tarun","colour":15105570,"pos":[11,-11],"provokes":"Being cut off mid-story, or being told his chatter is wasting time.","persona":"You fry bajjis on the beach road and you talk constantly, about\ncricket, about the weather, about your brother in Dubai. You saw the tempo leave\nbut you bury it under chatter and will not get to the point unless the player\nactually engages with your digressions. Rush you and you just start a new story.\nPlay along once and you deliver it: it went north towards the harbour gate, and\nthe driver was not Selvi''s usual boy.","mission":{"title":"Let Him Finish","brief":"Humour Anbu''s rambling, and he''ll get to what he saw.","successCriteria":"The player engaged with Anbu''s tangent instead of pushing him, and Anbu has said the tempo went north to the harbour gate with an unfamiliar driver.","reward":200},"clue":"The tempo went north to the harbour gate. The driver was a stranger.","lesson":[{"npc":{"native":"வணக்கம்","roman":"Vanakkam","en":"Hello"},"prompt":{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"எனக்கு உதவி வேண்டும்","roman":"Enakku udhavi vendum","en":"I need help"},"prompt":{"native":"புரியவில்லை","roman":"Puriyavillai","en":"I do not understand"}},{"npc":{"native":"மெதுவாக சொல்லுங்க","roman":"Meduvaa sollunga","en":"Please say it slowly"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]},{"id":"iyer","name":"Iyer Sir","role":"Temple Priest","speaker":"anand","colour":16044095,"pos":[-13,12],"provokes":"Threats of revenge, or disrespect towards the temple.","persona":"You are the priest at the small shore temple. You are gentle,\nunhurried and speak in proverbs. You know who took the tempo because he came to\nyou afterwards, and you are bound by that. You will not name him to someone\nseeking revenge, but if the player convinces you their aim is to get Selvi''s\nlivelihood back rather than to punish anyone, you tell them: Dass, the boat\nowner, took it, and it is behind the ice factory.","mission":{"title":"Not For Revenge","brief":"Convince Iyer you want the tempo back, not punishment.","successCriteria":"The player made clear their goal is recovering Selvi''s livelihood rather than revenge, and Iyer has named Dass and the ice factory.","reward":200},"clue":"Dass the boat owner took it. It is parked behind the ice factory.","requiresClues":2,"lesson":[{"npc":{"native":"வணக்கம்","roman":"Vanakkam","en":"Hello"},"prompt":{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"எனக்கு உதவி வேண்டும்","roman":"Enakku udhavi vendum","en":"I need help"},"prompt":{"native":"புரியவில்லை","roman":"Puriyavillai","en":"I do not understand"}},{"npc":{"native":"மெதுவாக சொல்லுங்க","roman":"Meduvaa sollunga","en":"Please say it slowly"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]},{"id":"dass","name":"Dass","role":"Boat Owner","speaker":"vijay","colour":9323693,"pos":[14,12],"provokes":"Being called a thief outright before his debt is acknowledged.","persona":"You are a boat owner who took Selvi''s tempo. You are not a\ncareer thief, Selvi''s late husband owed you for a season of diesel and you\ndecided to collect it yourself. You are defensive and proud, and you will deny\neverything to anyone who accuses you outright. If the player shows they\nunderstand you were owed, and offers a way to settle it that isn''t theft, you\nrelent and return the tempo. Accusation hardens you; acknowledgement moves you.","mission":{"title":"The Diesel Debt","brief":"Get Dass to return the tempo, accusing him will only harden him.","successCriteria":"The player acknowledged Dass was genuinely owed money rather than only accusing him, and Dass has agreed to return the tempo.","reward":400},"clue":"Dass returns the tempo. The debt goes to the panchayat instead.","requiresClues":3,"lesson":[{"npc":{"native":"வணக்கம்","roman":"Vanakkam","en":"Hello"},"prompt":{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"எனக்கு உதவி வேண்டும்","roman":"Enakku udhavi vendum","en":"I need help"},"prompt":{"native":"புரியவில்லை","roman":"Puriyavillai","en":"I do not understand"}},{"npc":{"native":"மெதுவாக சொல்லுங்க","roman":"Meduvaa sollunga","en":"Please say it slowly"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]},{"id":"local-guide","name":"City Guide","role":"Local Resident","speaker":"rohan","colour":3447003,"pos":[10,0],"provokes":"Insulting the city or refusing to speak.","persona":"You are a friendly local resident. You love talking about the culture, history, and food of your city. You answer in the local language, but you are very patient. You want the player to practice speaking. If they make a mistake, gently encourage them.","mission":{"title":"Chit Chat","brief":"Just say hello and talk about the city.","successCriteria":"The player talked to you.","reward":50},"clue":"The city is beautiful.","lesson":[]}],"finale":{"title":"TEMPO RETURNED","text":"The catch reaches the market by eleven. The diesel debt goes to the panchayat, where it should have gone a year ago. Selvi still doesn''t thank you, but she sends fish."}}'::jsonb
