ন","roman":"Ei nin","en":"Here you go"}},{"npc":{"native":"এই যে কফি","roman":"Ei je coffee","en":"Here is the coffee"},"prompt":{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}}],"hard":[{"npc":{"native":"কী খাবেন?","roman":"Ki khaben?","en":"What will you have?"},"prompt":{"native":"একটা ফিল্টার কফি দিন","roman":"Ekta filter coffee din","en":"Give me one filter coffee"}},{"npc":{"native":"গরম না ঠাণ্ডা?","roman":"Gorom na thanda?","en":"Hot or cold?"},"prompt":{"native":"গরম কফি","roman":"Gorom coffee","en":"Hot coffee"}},{"npc":{"native":"চিনি কতটা?","roman":"Chini kotota?","en":"How much sugar?"},"prompt":{"native":"একটু কম","roman":"Ektu kom","en":"A little less sugar"}},{"npc":{"native":"আর কিছু লাগবে?","roman":"Aar kichu lagbe?","en":"Anything else?"},"prompt":{"native":"না, শুধু কফি","roman":"Na, shudhu coffee","en":"No, just coffee"}},{"npc":{"native":"ত্রিশ টাকা","roman":"Trish taka","en":"Thirty rupees"},"prompt":{"native":"এই নিন","roman":"Ei nin","en":"Here you go"}},{"npc":{"native":"খুচরো আছে?","roman":"Khuchro ache?","en":"Do you have change?"},"prompt":{"native":"হ্যাঁ, এই যে","roman":"Haa, ei je","en":"Yes, here it is"}},{"npc":{"native":"এই যে কফি","roman":"Ei je coffee","en":"Here is the coffee"},"prompt":{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}}]}},{"id":"park-gully-guide","districtId":"park-gully","kind":"guide","pos":[15,-15],"title":"Local Guide","brief":"Chat freely with a local resident about the city.","reward":50,"interactLabel":"Chat with Local","name":"City Guide","role":"Local Resident","speaker":"rohan","colour":3447003,"completionNote":"Nice chat!","lessons":{"easy":[],"medium":[],"hard":[]}}]}'::jsonb,
  district = '{"id":"park-gully","name":"Park Gully","city":"Kolkata","blurb":"Wet red brick, failing light, and a yellow taxi that didn''t come home.","coverImage":"/covers/park-gully.png","language":"bn-IN","languageLabel":"Bengali","native":"বাংলা","script":"Bengali","premise":"Bikash-da has driven the same yellow Ambassador for twenty-six years.\nIt went missing from the para on the night before Puja, with his father''s\nphotograph still clipped to the sun visor. He wants the photograph more than the\ncar, though he will not say so.","theme":{"sky":["#3f7fc9","#7a9fd8","#c4a0c8","#f0b48a","#ffd9a8"],"fog":12089946,"fogNear":50,"ground":11047808,"pavement":13679526,"plaza":14205868,"tarmac":4867144,"lane":15719598,"buildings":[15229786,16106590,11060330,15771768,13924714,16246446,12622470],"canopies":[14694699,16106590,11893055],"leaf":4692542,"trunk":6047286,"sunColour":16768174,"sunIntensity":1.85,"ambient":0.3,"hemiSky":13031152,"hemiGround":11568230,"hemiIntensity":0.52,"archStyle":"colonial","autos":6,"cars":8,"autoCanopy":16106776,"exposure":1.12,"landmark":"kolkata"},"phrases":[{"native":"নমস্কার","roman":"Nomoshkar","en":"Hello"},{"native":"কত?","roman":"Koto?","en":"How much?"},{"native":"একটু সাহায্য করুন","roman":"Ektu shahajjo korun","en":"Please help a little"},{"native":"আমি বুঝতে পারছি না","roman":"Ami bujhte parchi na","en":"I do not understand"},{"native":"আস্তে বলুন","roman":"Aste bolun","en":"Please speak slowly"},{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}],"npcs":[{"id":"bikash","name":"Bikash-da","role":"Taxi Driver","speaker":"soham","colour":16044095,"pos":[-9,-6],"provokes":"Pity, or treating the Ambassador as merely an old car.","persona":"You have driven the same yellow Ambassador for twenty-six years\nand it is gone. You are dignified and understated, you refuse to appear\ndistressed about a mere vehicle, and you steer the conversation to Puja\npreparations instead. What you actually cannot bear is that your late father''s\nphotograph was clipped to the sun visor. You will not volunteer this. Only if the\nplayer asks gently about what was inside the car do you admit it, and give the\nplate: WB-04-2847.","mission":{"title":"What Was Inside","brief":"Ask gently about what was in the car, not just the car.","successCriteria":"The player asked about the contents or what mattered to him personally, and Bikash has admitted the photograph and given the number plate.","reward":200},"clue":"Yellow Ambassador, WB-04-2847. His father''s photograph is clipped to the sun visor.","lesson":[{"npc":{"native":"নমস্কার","roman":"Nomoshkar","en":"Hello"},"prompt":{"native":"কত?","roman":"Koto?","en":"How much?"}},{"npc":{"native":"একটু সাহায্য করুন","roman":"Ektu shahajjo korun","en":"Please help a little"},"prompt":{"native":"আমি বুঝতে পারছি না","roman":"Ami bujhte parchi na","en":"I do not understand"}},{"npc":{"native":"আস্তে বলুন","roman":"Aste bolun","en":"Please speak slowly"},"prompt":{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}}]},{"id":"mitali","name":"Mitali","role":"Sweet Shop Owner","speaker":"ishita","colour":12597547,"pos":[11,-12],"provokes":"Being boring, or interrogating her like a policeman.","persona":"You run the sweet shop on the corner and the whole para passes\nthrough it. You are quick, teasing, and you enjoy making people work for\ninformation. You will not answer a plain question plainly, you want the player\nto be interesting. Bore you and you go back to the sandesh. Make you laugh, or\ntell you something you didn''t know, and you give it up: the taxi was driven off\nby someone who knew where the spare key was kept.","mission":{"title":"Make Her Laugh","brief":"Be interesting, not efficient. Mitali rewards charm.","successCriteria":"The player amused Mitali or told her something genuinely interesting rather than only interrogating her, and she has revealed the thief knew where the spare key was.","reward":200},"clue":"Whoever took it knew where the spare key was kept, not a stranger.","lesson":[{"npc":{"native":"নমস্কার","roman":"Nomoshkar","en":"Hello"},"prompt":{"native":"কত?","roman":"Koto?","en":"How much?"}},{"npc":{"native":"একটু সাহায্য করুন","roman":"Ektu shahajjo korun","en":"Please help a little"},"prompt":{"native":"আমি বুঝতে পারছি না","roman":"Ami bujhte parchi na","en":"I do not understand"}},{"npc":{"native":"আস্তে বলুন","roman":"Aste bolun","en":"Please speak slowly"},"prompt":{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}}]},{"id":"paritosh","name":"Paritosh Dadu","role":"Rowak Elder","speaker":"ashutosh","colour":8359053,"pos":[-14,11],"provokes":"Disrespect towards elders, or rushing him.","persona":"You are eighty-one and you sit on the rowak watching the para\nfrom morning to night. You are wry and slightly deaf and you will happily\ndiscuss the decline of Bengali football for an hour. You know exactly who took\nit, Bikash''s own nephew, Nazrul, and you are protecting the family''s name. You\nwill only speak if the player convinces you that keeping the secret will hurt\nBikash more than the truth will.","mission":{"title":"The Para Remembers","brief":"Convince Dadu that silence hurts Bikash more than the truth.","successCriteria":"The player argued convincingly that protecting the secret harms Bikash more than revealing it, and Paritosh has named Nazrul as the nephew who took it.","reward":200},"clue":"Bikash''s own nephew Nazrul took it. He runs a garage two lanes over.","requiresClues":1,"lesson":[{"npc":{"native":"নমস্কার","roman":"Nomoshkar","en":"Hello"},"prompt":{"native":"কত?","roman":"Koto?","en":"How much?"}},{"npc":{"native":"একটু সাহায্য করুন","roman":"Ektu shahajjo korun","en":"Please help a little"},"prompt":{"native":"আমি বুঝতে পারছি না","roman":"Ami bujhte parchi na","en":"I do not understand"}},{"npc":{"native":"আস্তে বলুন","roman":"Aste bolun","en":"Please speak slowly"},"prompt":{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}}]},{"id":"nazrul","name":"Nazrul","role":"Garage Owner","speaker":"kabir","colour":2600544,"pos":[14,11],"provokes":"Being called a thief, or threatening to tell Bikash before he is ready.","persona":"You are Bikash''s nephew and you took his taxi. You did not steal\nit to sell it, you took it because the engine was failing and your uncle would\nnever accept help or admit he could not afford the rebuild, so you did it behind\nhis back and planned to return it after Puja. You are ashamed and braced for an\naccusation. If the player treats this as theft you shut down completely. If they\ngrasp that this was clumsy love, you break, and you ask them to help you tell\nhim.","mission":{"title":"Clumsy Love","brief":"This isn''t a theft. Work out what it actually is.","successCriteria":"The player recognised Nazrul acted out of care rather than greed, and Nazrul has admitted the engine rebuild and agreed to face Bikash.","reward":400},"clue":"Nazrul rebuilt the engine as a gift. The photograph never left the visor.","requiresClues":3,"lesson":[{"npc":{"native":"নমস্কার","roman":"Nomoshkar","en":"Hello"},"prompt":{"native":"কত?","roman":"Koto?","en":"How much?"}},{"npc":{"native":"একটু সাহায্য করুন","roman":"Ektu shahajjo korun","en":"Please help a little"},"prompt":{"native":"আমি বুঝতে পারছি না","roman":"Ami bujhte parchi na","en":"I do not understand"}},{"npc":{"native":"আস্তে বলুন","roman":"Aste bolun","en":"Please speak slowly"},"prompt":{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}}]},{"id":"local-guide","name":"City Guide","role":"Local Resident","speaker":"rohan","colour":3447003,"pos":[10,0],"provokes":"Insulting the city or refusing to speak.","persona":"You are a friendly local resident. You love talking about the culture, history, and food of your city. You answer in the local language, but you are very patient. You want the player to practice speaking. If they make a mistake, gently encourage them.","mission":{"title":"Chit Chat","brief":"Just say hello and talk about the city.","successCriteria":"The player talked to you.","reward":50},"clue":"The city is beautiful.","lesson":[]}],"finale":{"title":"COMING HOME","text":"The Ambassador comes back on the second day of Puja with a rebuilt engine and the photograph exactly where it was. Bikash-da says nothing at all about the engine, which is how you know."}}'::jsonb
WHERE id = 'park-gully';

