  district = '{"id":"charminar-lane","name":"Charminar Lane","city":"Hyderabad","blurb":"Mirchi smoke, afternoon haze, and an auto gone from the old city lane.","coverImage":"/covers/charminar-lane.jpg","language":"te-IN","languageLabel":"Telugu","native":"తెలుగు","script":"Telugu","premise":"Irfan Bhai''s auto, loaded with wedding biryani orders for the evening,\nvanished from the lane while he was arguing about parking. Three people on this\nstreet saw pieces of it. None of them will simply tell you.","theme":{"sky":["#5a7fd8","#8b9fe4","#c9a4cc","#eeb894","#f8dcbc"],"fog":13935988,"fogNear":55,"ground":11049868,"pavement":12893100,"plaza":13682358,"tarmac":4869462,"lane":15655616,"buildings":[15260872,12077658,5214102,10135712,15909544,13214247,9076620],"canopies":[12077658,5214102,16106810],"leaf":4164178,"trunk":6048318,"sunColour":16772808,"sunIntensity":2,"ambient":0.3,"hemiSky":14865663,"hemiGround":12293220,"hemiIntensity":0.55,"archStyle":"mughal","autos":8,"cars":7,"autoCanopy":16106776,"exposure":1.1,"landmark":"hyderabad"},"phrases":[{"native":"నమస్కారం","roman":"Namaskaram","en":"Hello"},{"native":"ఎంత?","roman":"Enta?","en":"How much?"},{"native":"నాకు సహాయం కావాలి","roman":"Naaku sahaayam kaavaali","en":"I need help"},{"native":"అర్థం కాలేదు","roman":"Artham kaaledu","en":"I do not understand"},{"native":"నెమ్మదిగా చెప్పండి","roman":"Nemmadhiga cheppandi","en":"Please say it slowly"},{"native":"ధన్యవాదాలు","roman":"Dhanyavaadaalu","en":"Thank you"}],"npcs":[{"id":"irfan","name":"Irfan Bhai","role":"Auto Driver","speaker":"rahul","colour":15965202,"pos":[-8,-6],"provokes":"Mocking the biryani orders or rushing him past the wedding deadline.","persona":"Your auto with evening biryani orders was taken from the lane.\nYou are panicking about the wedding caterer who prepaid. If the player is calm\nand practical you give the plate: green auto TS-09-AB-4410, last seen near the mirchi stall.","mission":{"title":"Biryani Deadline","brief":"Calm Irfan enough t