  district = '{"id":"manek-chowk","name":"Manek Chowk","city":"Ahmedabad","blurb":"Night-market glow, fafda crackle, and a delivery scooter gone from the square.","coverImage":"/covers/manek-chowk.jpg","language":"gu-IN","languageLabel":"Gujarati","native":"ગુજરાતી","script":"Gujarati","premise":"Jignesh bhai''s delivery scooter, loaded with sweet-shop boxes for the\nmorning wedding orders, vanished from Manek Chowk while he was arguing about\nparking. Three people on this street saw pieces of it. In the old city nobody\nsimply tells a stranger anything.","theme":{"sky":["#2a72c8","#5c96dc","#9ab6e0","#f0c98a","#ffe6b4"],"fog":13935988,"fogNear":58,"ground":13218958,"pavement":14469542,"plaza":15127986,"tarmac":4868946,"lane":16443568,"buildings":[16445656,15895580,3104680,16106810,12731695,15260088,9137998],"canopies":[15895580,3104680,14698554],"leaf":5941317,"trunk":8019004,"sunColour":16773840,"sunIntensity":2.05,"ambient":0.3,"hemiSky":14477567,"hemiGround":13083249,"hemiIntensity":0.55,"archStyle":"mughal","autos":8,"cars":7,"autoCanopy":16106776,"exposure":1.1,"landmark":"ahmedabad"},"phrases":[{"native":"નમસ્તે","roman":"Namaste","en":"Hello"},{"native":"કેટલા?","roman":"Ketlaa?","en":"How much?"},{"native":"મને મદદ જોઈએ","roman":"Mane madad joie","en":"I need help"},{"native":"સમજાયું નહીં","roman":"Samjaayu nahin","en":"I do not understand"},{"native":"ધીમેથી કહો","roman":"Dheemethi kaho","en":"Please say it slowly"},{"native":"આભાર","roman":"Aabhaar","en":"Thank you"}],"npcs":[{"id":"jignesh","name":"Jignesh Bhai","role":"Sweet Delivery","speaker":"rahul","colour":15965202,"pos":[-8,-6],"provokes":"Mocking the wedding orders or rushing him past the delivery deadline.","persona":"Your scooter with mithai boxes for the morning wedding is gone.\nYou are panicking about the caterer who prepaid. If the player is calm and\npractical you give the details: red scooter GJ-01-HX-3344, last seen near the\njewellery lane.","mission":{"title":"Mithai Deadline","brief":"Calm Jignesh enough to get the scooter description.","successCriteria":"The player stayed calm and practical and Jignesh gave colour and number plate.","reward":200},"clue":"Red scooter, GJ-01-HX-3344, near the jewellery lane.","lesson":[{"npc":{"native":"નમસ્તે","roman":"Namaste","en":"Hello"},"prompt":{"native":"કેટલા?","roman":"Ketlaa?","en":"How much?"}},{"npc":{"native":"મને મદદ જોઈએ","roman":"Mane madad joie","en":"I need help"},"prompt":{"native":"સમજાયું નહીં","roman":"Samjaayu nahin","en":"I do not understand"}},{"npc":{"native":"ધીમેથી કહો","roman":"Dheemethi kaho","en":"Please say it slowly"},"prompt":{"native":"આભાર","roman":"Aabhaar","en":"Thank you"}}]},{"id":"heena","name":"Heena","role":"Fafda-Jalebi Stall","speaker":"neha","colour":15158332,"pos":[10,-11],"provokes":"Calling fafda ''crackers'' or skipping a proper order.","persona":"You fry fafda and jalebi at the chowk and saw the scooter leave.\nYou won''t talk to someone who won''t buy properly. Order in Gujarati politely\nand you say: two boys on another scooter towed it toward the pol gate.","mission":{"title":"Fafda First","brief":"Order properly, then ask what she saw.","successCriteria":"The player ordered politely and Heena described the boys and direction.","reward":200},"clue":"Two boys towed it toward the pol gate on another scooter.","lesson":[{"npc":{"native":"નમસ્તે","roman":"Namaste","en":"Hello"},"prompt":{"native":"કેટલા?","roman":"Ketlaa?","en":"How much?"}},{"npc":{"native":"મને મદદ જોઈએ","roman":"Mane madad joie","en":"I need help"},"prompt":{"native":"સમજાયું નહીં","roman":"Samjaayu nahin","en":"I do not understand"}},{"npc":{"native":"ધીમેથી કહો","roman":"Dheemethi kaho","en":"Please say it slowly"},"prompt":{"native":"આભાર","roman":"Aabhaar","en":"Thank you"}}]},{"id":"mitesh","name":"Mitesh","role":"Jewellery Shop","speaker":"aditya","colour":3447003,"pos":[-13,11],"provokes":"Haggling like a tourist or treating the pol as a backdrop.","persona":"You sell silver near the chowk. You know who has the scooter but\nyou respect discretion. Show you care about Jignesh''s order not drama, and you\nname Dhaval at the scooter garage behind the clock tower.","mission":{"title":"Not A Backdrop","brief":"Show you care about the delivery, not spectacle.","successCriteria":"The player focused on recovering the scooter for Jignesh and Mitesh named Dhaval and the garage.","reward":200},"clue":"Dhaval at the garage behind the clock tower has it.","requiresClues":2,"lesson":[{"npc":{"native":"નમસ્તે","roman":"Namaste","en":"Hello"},"prompt":{"native":"કેટલા?","roman":"Ketlaa?","en":"How much?"}},{"npc":{"native":"મને મદદ જોઈએ","roman":"Mane madad joie","en":"I need help"},"prompt":{"native":"સમજાયું નહીં","roman":"Samjaayu nahin","en":"I do not understand"}},{"npc":{"native":"ધીમેથી કહો","roman":"Dheemethi kaho","en":"Please say it slowly"},"prompt":{"native":"આભાર","roman":"Aabhaar","en":"Thank you"}}]},{"id":"dhaval","name":"Dhaval","role":"Scooter Mechanic","speaker":"kabir","colour":2899536,"pos":[13,12],"provokes":"Calling him a thief before hearing why the scooter is there.","persona":"The scooter is in your shop; cousins borrowed it without asking\nJignesh. You fix scooters, you are not a thief. Separate you from the cousins\nand offer a face-saving return before the wedding, and you agree.","mission":{"title":"Cousins, Not Crooks","brief":"Give Dhaval a way to return the scooter without shame.","successCriteria":"The player distinguished Dhaval from the borrowers and offered a face-saving return.","reward":400},"clue":"Scooter returned with mithai boxes still sealed.","requiresClues":3,"lesson":[{"npc":{"native":"નમસ્તે","roman":"Namaste","en":"Hello"},"prompt":{"native":"કેટલા?","roman":"Ketlaa?","en":"How much?"}},{"npc":{"native":"મને મદદ જોઈએ","roman":"Mane madad joie","en":"I need help"},"prompt":{"native":"સમજાયું નહીં","roman":"Samjaayu nahin","en":"I do not understand"}},{"npc":{"native":"ધીમેથી કહો","roman":"Dheemethi kaho","en":"Please say it slowly"},"prompt":{"native":"આભાર","roman":"Aabhaar","en":"Thank you"}}]},{"id":"local-guide","name":"City Guide","role":"Local Resident","speaker":"rohan","colour":3447003,"pos":[10,0],"provokes":"Insulting the city or refusing to speak.","persona":"You are a friendly local resident. You love talking about the culture, history, and food of your city. You answer in the local language, but you are very patient. You want the player to practice speaking. If they make a mistake, gently encourage them.","mission":{"title":"Chit Chat","brief":"Just say hello and talk about the city.","successCriteria":"The player talked to you.","reward":50},"clue":"The city is beautiful.","lesson":[]}],"finale":{"title":"MITHAI SAVED","text":"The scooter rolls back before the wedding breakfast. Jignesh still argues about parking."}}'::jsonb
