  district = '{"id":"dadar-chowk","name":"Dadar Chowk","city":"Mumbai","blurb":"Local trains, vada pav steam, and a share-auto gone from the square.","coverImage":"/covers/dadar-chowk.jpg","language":"mr-IN","languageLabel":"Marathi","native":"मराठी","script":"Devanagari","premise":"Sunil dada''s share-auto, the one that does the Dadar–Bandra run every\nmorning, was taken from the chowk while he was at the station toilet. Three\npeople on this street saw a piece of what happened. In Mumbai nobody simply\ntells a stranger anything.","theme":{"sky":["#2585cd","#4fa4e2","#8ac6ee","#d0e6f6","#f8e8c8"],"fog":12109004,"fogNear":55,"ground":11576718,"pavement":12892578,"plaza":13813424,"tarmac":4869460,"lane":15787704,"buildings":[15918020,11057340,14709295,4172266,15896480,16445133,8229544],"canopies":[15743275,2080619,16752412],"leaf":5217087,"trunk":7033400,"sunColour":16773848,"sunIntensity":2.1,"ambient":0.31,"hemiSky":13822207,"hemiGround":11049590,"hemiIntensity":0.57,"archStyle":"colonial","autos":10,"cars":8,"autoCanopy":16106776,"exposure":1.1,"landmark":"mumbai"},"phrases":[{"native":"नमस्कार","roman":"Namaskar","en":"Hello"},{"native":"किती?","roman":"Kiti?","en":"How much?"},{"native":"मला मदत हवी आहे","roman":"Mala madat havi aahe","en":"I need help"},{"native":"समजले नाही","roman":"Samajle naahi","en":"I do not understand"},{"native":"हळूहळू सांगा","roman":"Halu-halu saanga","en":"Please say it slowly"},{"native":"धन्यवाद","roman":"Dhanyavaad","en":"Thank you"}],"npcs":[{"id":"sunil","name":"Sunil Dada","role":"Share-Auto Driver","speaker":"rahul","colour":15965202,"pos":[-8,-6],"provokes":"Joking about Mumbai traffic or implying he left the keys in.","persona":"Your share-auto is gone and forty regulars will miss the Bandra run.\nYou are angry at the city, not sad. If the player is direct and respects your\nroute, you give the plate: black-yellow MH-01-CD-7788, last seen near the bridge.","mission":{"title":"Bandra Run","brief":"Get Sunil to give the auto d