  district = '{"id":"hall-bazaar","name":"Hall Bazaar","city":"Amritsar","blurb":"Golden Temple bells, lassi steam, and a cycle-cart gone from the bazaar lane.","coverImage":"/covers/hall-bazaar.jpg","language":"pa-IN","languageLabel":"Punjabi","native":"ਪੰਜਾਬੀ","script":"Gurmukhi","premise":"Gurpreet ji''s cycle-cart, the one that carries karah prasad tins to\nthe gurdwara stalls before sangat arrives, was taken from Hall Bazaar while he\nwas in langar. Three people on this street saw a piece of what happened. In\nAmritsar nobody simply tells a stranger anything.","theme":{"sky":["#3888cf","#68a6e0","#a8c6e8","#f0cf94","#ffe4b0"],"fog":15255672,"fogNear":62,"ground":12888958,"pavement":14074000,"plaza":14864544,"tarmac":4869460,"lane":16444072,"buildings":[16769658,16106810,15780682,11065520,16237744,15896480,15250569],"canopies":[16752412,2080619,15743275],"leaf":5217087,"trunk":7033400,"sunColour":16773836,"sunIntensity":2.15,"ambient":0.32,"hemiSky":16773336,"hemiGround":13081176,"hemiIntensity":0.58,"archStyle":"mughal","autos":8,"cars":6,"autoCanopy":16106776,"exposure":1.12,"landmark":"amritsar"},"phrases":[{"native":"ਸਤ ਸ੍ਰੀ ਅਕਾਲ","roman":"Sat sri akaal","en":"Hello"},{"native":"ਕਿੰਨੇ ਦਾ?","roman":"Kinne da?","en":"How much?"},{"native":"ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ","roman":"Mainu madad chaahidi hai","en":"I need help"},{"native":"ਸਮਝ ਨਹੀਂ ਆਇਆ","roman":"Samjh nahin aaya","en":"I do not understand"},{"native":"ਹੌਲੀ ਹੌਲੀ ਦੱਸੋ","roman":"Haouli haouli daso","en":"Please say it slowly"},{"native":"ਧੰਨਵਾਦ","roman":"Dhannvaad","en":"Thank you"}],"npcs":[{"id":"gurpreet","name":"Gurpreet Ji","role":"Prasad Cart","speaker":"rahul","colour":15965202,"pos":[-8,-6],"provokes":"Joking about langar portions or implying he was careless.","persona":"Your cycle-cart with karah prasad tins is gone and sangat will\narrive in an hour. You are worried, not loud. If the player is respectful and\npractical you give the details: green cart PB-02-AB-9912, last seen near the\nlassi lane.","mission":{"title":"Before Sangat","brief":"Get Gurpreet to describe the cart.","successCriteria":"The player was respectful and practical and Gurpreet gave colour and identifying details.","reward":200},"clue":"Green cart, PB-02-AB-9912, near the lassi lane.","lesson":[{"npc":{"native":"ਸਤ ਸ੍ਰੀ ਅਕਾਲ","roman":"Sat sri akaal","en":"Hello"},"prompt":{"native":"ਕਿੰਨੇ ਦਾ?","roman":"Kinne da?","en":"How much?"}},{"npc":{"native":"ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ","roman":"Mainu madad chaahidi hai","en":"I need help"},"prompt":{"native":"ਸਮਝ ਨਹੀਂ ਆਇਆ","roman":"Samjh nahin aaya","en":"I do not understand"}},{"npc":{"native":"ਹੌਲੀ ਹੌਲੀ ਦੱਸੋ","roman":"Haouli haouli daso","en":"Please say it slowly"},"prompt":{"native":"ਧੰਨਵਾਦ","roman":"Dhannvaad","en":"Thank you"}}]},{"id":"simran","name":"Simran","role":"Lassi Stall","speaker":"neha","colour":15158332,"pos":[10,-11],"provokes":"Calling lassi ''yogurt drink'' or skipping the order.","persona":"You churn lassi by the bazaar and saw the cart leave. You won''t\ntalk to someone who won''t buy properly. Order in Punjabi politely and you say:\ntwo boys in white kurta took it toward the clock tower.","mission":{"title":"Lassi First","brief":"Order properly, then ask what she saw.","successCriteria":"The player ordered politely and Simran described the boys and direction.","reward":200},"clue":"Two boys in white kurta took it toward the clock tower.","lesson":[{"npc":{"native":"ਸਤ ਸ੍ਰੀ ਅਕਾਲ","roman":"Sat sri akaal","en":"Hello"},"prompt":{"native":"ਕਿੰਨੇ ਦਾ?","roman":"Kinne da?","en":"How much?"}},{"npc":{"native":"ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ","roman":"Mainu madad chaahidi hai","en":"I need help"},"prompt":{"native":"ਸਮਝ ਨਹੀਂ ਆਇਆ","roman":"Samjh nahin aaya","en":"I do not understand"}},{"npc":{"native":"ਹੌਲੀ ਹੌਲੀ ਦੱਸੋ","roman":"Haouli haouli daso","en":"Please say it slowly"},"prompt":{"native":"ਧੰਨਵਾਦ","roman":"Dhannvaad","en":"Thank you"}}]},{"id":"harjeet","name":"Harjeet","role":"Kirpan Smith","speaker":"aditya","colour":3447003,"pos":[-13,11],"provokes":"Treating the bazaar as a photo walk only.","persona":"You work metal near the bazaar. You know who has the cart because\nhe wheeled it behind your shed. You respect people who aren''t looking for a\nfight. Show you want the prasad delivered and you name Balbir at the cart shed\nbehind Hall Gate.","mission":{"title":"Not A Photo Walk","brief":"Show you want the cart back for sangat, not a scene.","successCriteria":"The player focused on the prasad delivery and Harjeet named Balbir and the shed.","reward":200},"clue":"Balbir at the cart shed behind Hall Gate has it.","requiresClues":2,"lesson":[{"npc":{"native":"ਸਤ ਸ੍ਰੀ ਅਕਾਲ","roman":"Sat sri akaal","en":"Hello"},"prompt":{"native":"ਕਿੰਨੇ ਦਾ?","roman":"Kinne da?","en":"How much?"}},{"npc":{"native":"ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ","roman":"Mainu madad chaahidi hai","en":"I need help"},"prompt":{"native":"ਸਮਝ ਨਹੀਂ ਆਇਆ","roman":"Samjh nahin aaya","en":"I do not understand"}},{"npc":{"native":"ਹੌਲੀ ਹੌਲੀ ਦੱਸੋ","roman":"Haouli haouli daso","en":"Please say it slowly"},"prompt":{"native":"ਧੰਨਵਾਦ","roman":"Dhannvaad","en":"Thank you"}}]},{"id":"balbir","name":"Balbir","role":"Cart Repair","speaker":"kabir","colour":2899536,"pos":[13,12],"provokes":"Calling him a thief before hearing why the cart is there.","persona":"The cart is in your shed; your nephew borrowed it to move steel\nwithout asking Gurpreet. You fix carts, you are not a thief. Separate you from\nyour nephew and offer a face-saving return before sangat, and you agree.","mission":{"title":"Nephew, Not Thief","brief":"Give Balbir a way to return the cart without shame.","successCriteria":"The player distinguished Balbir from the borrower and offered a face-saving return.","reward":400},"clue":"Cart returned with prasad tins still sealed.","requiresClues":3,"lesson":[{"npc":{"native":"ਸਤ ਸ੍ਰੀ ਅਕਾਲ","roman":"Sat sri akaal","en":"Hello"},"prompt":{"native":"ਕਿੰਨੇ ਦਾ?","roman":"Kinne da?","en":"How much?"}},{"npc":{"native":"ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ","roman":"Mainu madad chaahidi hai","en":"I need help"},"prompt":{"native":"ਸਮਝ ਨਹੀਂ ਆਇਆ","roman":"Samjh nahin aaya","en":"I do not understand"}},{"npc":{"native":"ਹੌਲੀ ਹੌਲੀ ਦੱਸੋ","roman":"Haouli haouli daso","en":"Please say it slowly"},"prompt":{"native":"ਧੰਨਵਾਦ","roman":"Dhannvaad","en":"Thank you"}}]},{"id":"local-guide","name":"City Guide","role":"Local Resident","speaker":"rohan","colour":3447003,"pos":[10,0],"provokes":"Insulting the city or refusing to speak.","persona":"You are a friendly local resident. You love talking about the culture, history, and food of your city. You answer in the local language, but you are very patient. You want the player to practice speaking. If they make a mistake, gently encourage them.","mission":{"title":"Chit Chat","brief":"Just say hello and talk about the city.","successCriteria":"The player talked to you.","reward":50},"clue":"The city is beautiful.","lesson":[]}],"finale":{"title":"PRASAD DELIVERED","text":"The cart is back before sangat fills the lane. Gurpreet still says nothing about the nephew."}}'::jsonb
