  district = '{"id":"lingaraj-lane","name":"Lingaraj Lane","city":"Bhubaneswar","blurb":"Temple bells, pakhala steam, and a flower tempo gone from the lane.","coverImage":"/covers/lingaraj-lane.jpg","language":"od-IN","languageLabel":"Odia","native":"ଓଡ଼ିଆ","script":"Odia","premise":"Biju bhai''s tempo, loaded with marigold garlands for Lingaraj before\nthe morning arati, vanished from the lane while he was at the tea stall. Three\npeople on this street saw pieces of it. Near the temple nobody simply tells a\nstranger anything.","theme":{"sky":["#3c80c8","#6f9dd8","#a8b0d0","#e8b48c","#fbdcb4"],"fog":13150344,"fogNear":65,"ground":12100498,"pavement":13351078,"plaza":14207156,"tarmac":4999764,"lane":16115396,"buildings":[15383174,14698554,11568480,11065520,16237744,11057340,14709295],"canopies":[15743275,16752412,2080619],"leaf":5217087,"trunk":7033400,"sunColour":16772288,"sunIntensity":1.95,"ambient":0.3,"hemiSky":15785168,"hemiGround":11306340,"hemiIntensity":0.54,"archStyle":"dravidian","autos":7,"cars":6,"autoCanopy":16106776,"exposure":1.1,"landmark":"bhubaneswar"},"phrases":[{"native":"ନମସ୍କାର","roman":"Namaskaar","en":"Hello"},{"native":"କେତେ?","roman":"Kete?","en":"How much?"},{"native":"ମୋତେ ସାହାଯ୍ୟ ଦରକାର","roman":"Mote sahaayya darakaar","en":"I need help"},{"native":"ବୁଝିଲି ନାହିଁ","roman":"Bujhili nahin","en":"I do not understand"},{"native":"ଧୀରେ କୁହ","roman":"Dheere kuha","en":"Please say it slowly"},{"native":"ଧନ୍ୟବାଦ","roman":"Dhanyabaad","en":"Thank you"}],"npcs":[{"id":"biju","name":"Biju Bhai","role":"Flower Tempo Driver","speaker":"rahul","colour":15965202,"pos":[-8,-6],"provokes":"Rushing him past arati or treating the flowers as decoration only.","persona":"Your tempo with garlands for Lingaraj is gone and arati is in an\nhour. You are frantic about the priest who prepaid. If the player is calm and\npractical you give the plate: blue tempo OD-02-AB-6610, last seen near the\npakhala stall.","mission":{"title":"Before Arati","brief":"Calm Biju enough to get the tempo description.","successCriteria":"The player stayed calm and practical and Biju gave colour and number plate.","reward":200},"clue":"Blue tempo, OD-02-AB-6610, near the pakhala stall.","lesson":[{"npc":{"native":"ନମସ୍କାର","roman":"Namaskaar","en":"Hello"},"prompt":{"native":"କେତେ?","roman":"Kete?","en":"How much?"}},{"npc":{"native":"ମୋତେ ସାହାଯ୍ୟ ଦରକାର","roman":"Mote sahaayya darakaar","en":"I need help"},"prompt":{"native":"ବୁଝିଲି ନାହିଁ","roman":"Bujhili nahin","en":"I do not understand"}},{"npc":{"native":"ଧୀରେ କୁହ","roman":"Dheere kuha","en":"Please say it slowly"},"prompt":{"native":"ଧନ୍ୟବାଦ","roman":"Dhanyabaad","en":"Thank you"}}]},{"id":"purnima","name":"Purnima","role":"Pakhala Stall","speaker":"neha","colour":15158332,"pos":[10,-11],"provokes":"Calling pakhala ''leftover rice'' or skipping the order.","persona":"You serve pakhala by the lane and saw the tempo leave. You won''t\ntalk to someone who won''t order properly. Order in Odia politely and you say:\ntwo boys in dhotis drove it toward the tank road gate.","mission":{"title":"Pakhala First","brief":"Order properly, then ask what she saw.","successCriteria":"The player ordered politely and Purnima described the boys and direction.","reward":200},"clue":"Two boys in dhotis drove it toward the tank road gate.","lesson":[{"npc":{"native":"ନମସ୍କାର","roman":"Namaskaar","en":"Hello"},"prompt":{"native":"କେତେ?","roman":"Kete?","en":"How much?"}},{"npc":{"native":"ମୋତେ ସାହାଯ୍ୟ ଦରକାର","roman":"Mote sahaayya darakaar","en":"I need help"},"prompt":{"native":"ବୁଝିଲି ନାହିଁ","roman":"Bujhili nahin","en":"I do not understand"}},{"npc":{"native":"ଧୀରେ କୁହ","roman":"Dheere kuha","en":"Please say it slowly"},"prompt":{"native":"ଧନ୍ୟବାଦ","roman":"Dhanyabaad","en":"Thank you"}}]},{"id":"niranjan","name":"Niranjan","role":"Temple Flower Seller","speaker":"aditya","colour":3447003,"pos":[-13,11],"provokes":"Haggling during arati season or disrespect toward the shrine.","persona":"You sell flowers near Lingaraj. You know who has the tempo but\nyou respect discretion. Show you care about Biju''s delivery not drama, and you\nname Subhash at the garage behind the temple tank.","mission":{"title":"Respect The Shrine","brief":"Show you care about the garlands, not spectacle.","successCriteria":"The player focused on recovering the tempo for Biju and Niranjan named Subhash and the garage.","reward":200},"clue":"Subhash at the garage behind the temple tank has it.","requiresClues":2,"lesson":[{"npc":{"native":"ନମସ୍କାର","roman":"Namaskaar","en":"Hello"},"prompt":{"native":"କେତେ?","roman":"Kete?","en":"How much?"}},{"npc":{"native":"ମୋତେ ସାହାଯ୍ୟ ଦରକାର","roman":"Mote sahaayya darakaar","en":"I need help"},"prompt":{"native":"ବୁଝିଲି ନାହିଁ","roman":"Bujhili nahin","en":"I do not understand"}},{"npc":{"native":"ଧୀରେ କୁହ","roman":"Dheere kuha","en":"Please say it slowly"},"prompt":{"native":"ଧନ୍ୟବାଦ","roman":"Dhanyabaad","en":"Thank you"}}]},{"id":"subhash","name":"Subhash","role":"Garage Hand","speaker":"kabir","colour":2899536,"pos":[13,12],"provokes":"Calling him a thief before hearing why the tempo is there.","persona":"The tempo is in your yard; cousins borrowed it without asking\nBiju. You fix tempos, you are not a thief. Separate you from the cousins and\noffer a face-saving return before arati, and you agree.","mission":{"title":"Cousins, Not Crooks","brief":"Give Subhash a way to return the tempo without shame.","successCriteria":"The player distinguished Subhash from the borrowers and offered a face-saving return.","reward":400},"clue":"Tempo returned with garlands still fresh.","requiresClues":3,"lesson":[{"npc":{"native":"ନମସ୍କାର","roman":"Namaskaar","en":"Hello"},"prompt":{"native":"କେତେ?","roman":"Kete?","en":"How much?"}},{"npc":{"native":"ମୋତେ ସାହାଯ୍ୟ ଦରକାର","roman":"Mote sahaayya darakaar","en":"I need help"},"prompt":{"native":"ବୁଝିଲି ନାହିଁ","roman":"Bujhili nahin","en":"I do not understand"}},{"npc":{"native":"ଧୀରେ କୁହ","roman":"Dheere kuha","en":"Please say it slowly"},"prompt":{"native":"ଧନ୍ୟବାଦ","roman":"Dhanyabaad","en":"Thank you"}}]},{"id":"local-guide","name":"City Guide","role":"Local Resident","speaker":"rohan","colour":3447003,"pos":[10,0],"provokes":"Insulting the city or refusing to speak.","persona":"You are a friendly local resident. You love talking about the culture, history, and food of your city. You answer in the local language, but you are very patient. You want the player to practice speaking. If they make a mistake, gently encourage them.","mission":{"title":"Chit Chat","brief":"Just say hello and talk about the city.","successCriteria":"The player talked to you.","reward":50},"clue":"The city is beautiful.","lesson":[]}],"finale":{"title":"ARATI SAVED","text":"The tempo rolls back before the bell. Biju still argues about tea breaks."}}'::jsonb
